<script>document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('money-type');if(!select)return;const sync=()=>{const type=select.value;document.querySelectorAll('[data-money-field]').forEach(label=>{const field=label.dataset.moneyField;const visible=field==='source'?type!=='receipt':field==='destination'?type!=='payment':type!=='transfer';label.classList.toggle('money-field-hidden',!visible);label.querySelector('select').required=visible;});};select.addEventListener('change',sync);sync();});</script>
